(14, 'social_linkedin', '#', '2022-08-15 22:14:52', '2022-12-05 22:02:14'),
(15, 'google_analytics', '', '2022-08-15 22:14:52', '2022-08-15 22:14:52'),
(16, 'facebook_pixels', '', '2022-08-15 22:14:52', '2022-08-15 22:14:52'),
(17, 'stripe_payment_method', '', '2022-08-15 22:14:52', '2022-08-15 22:14:52'),
(18, 'stripe_key', '', '2022-08-15 22:14:52', '2022-08-15 22:14:52'),
(19, 'stripe_secret_key', '', '2022-08-15 22:14:52', '2022-08-15 22:14:52'),
(20, 'paypal_payment_method', '', '2022-08-15 22:14:52', '2022-08-15 22:14:52'),
(21, 'paypal_client_id', '', '2022-08-15 22:14:52', '2022-08-15 22:14:52'),
(22, 'paypal_secret_id', '', '2022-08-15 22:14:52', '2022-08-15 22:14:52'),
(23, 'short_about', 'ইনোভা কম্পিউটার্স বিডি, বাংলাদেশের অন্যতম  আইটি প্রশিক্ষণ প্রতিষ্ঠান সেরা প্রশিক্ষণের সুযোগ প্রদান করে। এটি ২০১৮ সাল থেকে বেকারত্ব সমস্যা নির্মূলে গুরুত্বপূর্ণ ভূমিকা পালন করে আসছে। মানসম্পন্ন প্রশিক্ষণে সমৃদ্ধ এই ইনস্টিটিউটটি সৃজনশীলতা এবং আইটি-এর মধ্যে সামঞ্জস্য তৈরি করে তাদের প্রতিভা প্রকাশ করতে ব্যক্তিদের সাহায্য করতে কখনও ব্যর্থ হয়নি। আপনার পটভূমি যাই হোক না কেন, আমরা আপনার দক্ষতা বাড়াতে অভিজ্ঞ প্রশিক্ষকদের দ্বারা পরিচালিত ১২টি কোর্স অফার করছি। ইনোভা কম্পিউটার্স বিডি -এর আপগ্রেড সরঞ্জাম সহ ক্যাম্পাসকে অসাধারণভাবে সুসজ্জিত করা হয়েছে। আমাদের শিক্ষার্থীরা আমাদের সংস্কৃতি, পরিবেশ এবং অসামান্য প্রশিক্ষণ পদ্ধতিতে অনেক খুশি। আমরা আমাদের শিক্ষার্থীদের ভাল পরিষেবা প্রদান সম্পর্কে উত্সাহী. এইভাবে, এই ইনস্টিটিউটের শিক্ষার্থীরা সফল বিপণনকারী হতে পরিণত হয় এবং বিভিন্ন কোম্পানিতেও তাদের ক্যারিয়ার প্রতিষ্ঠা করে।', NULL, '2023-06-07 13:07:20');
