INSERT INTO `sliders` (`id`, `title`, `details`, `btnTxt`, `btnLink`, `dao`, `ddo`, `ddi`, `dai`, `IsActive`, `image`, `deleted_at`, `created_at`, `updated_at`) VALUES
(1, 'স্বাগতম <br> ইনোভা <br> কম্পিউটার্স বিডি তে', 'অভিজ্ঞ মেন্টর আর আপডেটেড কারিকুলাম নিয়ে  ইনোভা কম্পিউটার্স বিডি প্রস্তুত আপনার ক্যারিয়ার গড়ার অগ্রযাত্রায়। আমাদের ১২টিরও বেশি ট্রেন্ডি কোর্স থেকে আজই বেছে নিন আপনার পছন্দের কোর্স।\r\nআইটি আউটসোর্সিং এবং ফ্রিল্যান্সিং-এ ৬+ বছরের অভিজ্ঞতা  নিয়ে আমরা আছি আপনার কাছে। এখনি আমাদের সাথে যোগদান করুন! আমাদের সাথে আপনার আউটসোর্সিং ক্যারিয়ার গড়ুন এবং অবশ্যই একজন বিশ্বমানের ফ্রিল্যান্সার হোন।', 'ব্রাউজ কোর্স', 'https://innovacomputersbd.com/courses', 'fadeOutRight', '5', '.9', 'fadeInLeft', '1', NULL, NULL, '2022-12-05 17:27:23', '2023-06-06 20:36:01'),
(2, 'স্বাগতম <br> ইনোভা <br> কম্পিউটার্স বিডি তে', 'অভিজ্ঞ মেন্টর আর আপডেটেড কারিকুলাম নিয়ে  ইনোভা কম্পিউটার্স বিডি প্রস্তুত আপনার ক্যারিয়ার গড়ার অগ্রযাত্রায়। আমাদের ১২টিরও বেশি ট্রেন্ডি কোর্স থেকে আজই বেছে নিন আপনার পছন্দের কোর্স।\r\nআইটি আউটসোর্সিং এবং ফ্রিল্যান্সিং-এ ৬+ বছরের অভিজ্ঞতা  নিয়ে আমরা আছি আপনার কাছে। এখনি আমাদের সাথে যোগদান করুন! আমাদের সাথে আপনার আউটসোর্সিং ক্যারিয়ার গড়ুন এবং অবশ্যই একজন বিশ্বমানের ফ্রিল্যান্সার হোন।', 'ব্রাউজ কোর্স', 'https://innovacomputersbd.com/courses', 'fadeOutRight', '5', '.9', 'fadeInLeft', '1', NULL, NULL, '2022-12-05 17:58:56', '2023-06-06 20:38:54');
