INSERT INTO `success_stories` (`id`, `student_id`, `msg`, `video`, `IsActive`, `image`, `deleted_at`, `created_at`, `updated_at`) VALUES
(1, 125, 'ইনোভা কম্পিউটারস বিডি বাংলাদেশের একটি খুব ভালো মানের প্রশিক্ষণ প্রতিষ্ঠান। ইনোভা কম্পিউটারস বিডি সম্পর্কে আমার প্রিয় জিনিস হল তাদের কোর্স মডিউল। এই মডিউল অনুযায়ী শিখলে সবাই ভালো মানের ডিজাইনার হতে পারে। এবং তাদের 24/7 সমর্থন দুর্দান্ত। এবং আমাদের পরামর্শদাতা, সাহাব উদ্দিন স্যার খুব সহায়ক। এক কথায় যেকোনো বিষয়কে বোঝানোর স্টাইল অসাধারণ।', 'https://youtu.be/v-Yi2RRNS3A', 1, 'SuccessStory/vRpkqbKSJb28Yqd8Ke9UcGi1F.jpg', NULL, '2022-12-05 21:48:04', '2023-06-07 13:22:57');
